<?php
function order_return_balance($platform,$order,$pid){
 stock_platform($platform);$q=db()->prepare("SELECT COALESCE(SUM(qty),0) FROM outflows WHERE platform=? AND order_id=? AND product_id=? AND type='Order' AND reversed_by_request IS NULL");$q->execute([$platform,$order,$pid]);$original=(int)$q->fetchColumn();
 $q=db()->prepare('SELECT COALESCE(SUM(qty),0) FROM posted_returns WHERE platform=? AND original_ref=? AND product_id=? AND reversed=0');$q->execute([$platform,$order,$pid]);$returned=(int)$q->fetchColumn();
 $q=db()->prepare("SELECT COALESCE(SUM(qty),0) FROM inflows WHERE source_platform=? AND reference_no=? AND product_id=? AND type='Customer Return - Good' AND reversed_by_request IS NULL");$q->execute([$platform,$order,$pid]);$returned+=(int)$q->fetchColumn();
 // Staged legacy returns did not retain source_platform; their batch metadata retains it.
 $q=db()->prepare("SELECT i.qty,b.result_json FROM inflows i JOIN inflow_batches b ON b.id=i.batch_id WHERE i.reference_no=? AND i.product_id=? AND i.type='Customer Return - Good' AND COALESCE(i.source_platform,'')='' AND i.reversed_by_request IS NULL");$q->execute([$order,$pid]);foreach($q as $r)if((json_decode($r['result_json'],true)['return_platform']??'')===$platform)$returned+=(int)$r['qty'];
 $q=db()->prepare("SELECT COALESCE(SUM(qty),0) FROM non_sellable WHERE platform=? AND order_id=? AND product_id=? AND origin='Customer Return' AND reversed_by_request IS NULL");$q->execute([$platform,$order,$pid]);$returned+=(int)$q->fetchColumn();return ['original'=>$original,'returned'=>$returned,'remaining'=>max(0,$original-$returned)];
}
function return_batch($id,$lock=false){$q=db()->prepare('SELECT * FROM return_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$b=$q->fetch();if(!$b)throw new Exception('Return upload not found.');return $b;}
function return_match($item){if($mapped=product_code_lookup($item))return $mapped;$q=db()->prepare('SELECT id FROM products WHERE active=1 AND (master_sku=? OR normalized_name=?)');$q->execute([trim($item),norm($item)]);$rows=$q->fetchAll();return count($rows)===1?(int)$rows[0]['id']:0;}
function return_damage_only($batch){$rows=json_decode($batch['rows_json']??'[]',true);return is_array($rows)&&count($rows)>0&&!array_filter($rows,fn($r)=>($r['condition']??'')!=='Damaged / Leak');}
function return_requires_admin_review($analysis){foreach($analysis['rows'] as $row)if(isset($row['possible_duplicate'])&&($row['condition']??'')!=='Damaged / Leak')return true;return false;}
function return_uploader_allowed($batch,$analysis){if(!can_action('return_confirm'))return false;if(current_user()['role']==='Admin')return true;if(return_requires_admin_review($analysis))return false;if(return_damage_only($batch)||!empty($analysis['warnings']))return (int)$batch['created_by']===current_user()['id'];return true;}
function return_pending_damage_uploads(){return array_values(array_filter(db()->query("SELECT * FROM return_batches WHERE status='Review'")->fetchAll(),'return_damage_only'));}
function return_damage_inflow_exclusion_sql(){$pending=return_pending_damage_uploads();return $pending?' AND batch_ref NOT IN ('.implode(',',array_map(fn($r)=>db()->quote($r['batch_ref']),$pending)).')':'';}
function return_inflow_review_label($row,$meta){if(($row['batch_type']??'')!=='Order Return'||!in_array($row['status']??'',['Review','To Review','Pending Review'],true))return badge($row['status'],status_badge_class($row['status']));$rows=$meta['rows']??[];$damage=count($rows)>0&&!array_filter($rows,fn($r)=>($r['condition']??'')!=='Damaged / Leak');if(!$damage)return badge($row['status'],status_badge_class($row['status']));return '<span class="badge warn">'.((int)($row['error_count']??0)>0?'Needs Correction':'Awaiting Uploader Validation').'</span>';}
function return_analysis($b){$rows=json_decode($b['rows_json'],true)?:[];if(in_array($b['status'],['Posted','Reversed'],true))return ['rows'=>$rows,'errors'=>[],'warnings'=>[],'digest'=>''];$checked=[];$errors=[];$warnings=[];$used=[];$seen=[];foreach($rows as $row){$row['errors']=[];try{if(!empty($row['parse_error']))throw new Exception($row['parse_error']);$row['date']=process_date($row['date']);$row['platform']=stock_platform($row['platform']);$row['qty']=whole_number($row['qty'],'Quantity',1);if($row['qty']>100000000)throw new Exception('Quantity is too large.');$row['order']=trim((string)$row['order']);if($row['order']===''||strlen($row['order'])>100)throw new Exception('Order ID is required, up to 100 characters.');if(!in_array($row['condition'],['Good Item','Damaged / Leak','For Repackaging'],true))throw new Exception('Select Good Item, Damaged / Leak or For Repackaging.');if($row['condition']==='For Repackaging')packaging_require();$p=active_product((int)$row['product_id']);$row['product_name']=$p['name'];$row['sku']=$p['master_sku'];$balance=order_return_balance($row['platform'],$row['order'],$row['product_id']);$key=$row['platform'].'|'.$row['order'].'|'.$row['product_id'];$rowKey=hash('sha256',json_encode([$key,$row['date'],$row['qty'],$row['condition']]));if(isset($seen[$rowKey]))throw new Exception('Duplicate return row inside this file. Remove or consolidate the repeated row.');$seen[$rowKey]=true;$used[$key]=($used[$key]??0)+$row['qty'];$row['remaining_after']=max(0,$balance['remaining']-$used[$key]);$row+=$balance;if($balance['original']<=0)throw new Exception('Original posted order/product was not found on this platform.');if($used[$key]>$balance['remaining'])throw new Exception('Return exceeds remaining quantity: '.$balance['remaining'].' pcs. Original '.$balance['original'].'; previously returned '.$balance['returned'].'.');
 $q=db()->prepare("SELECT r.id,r.txn_date,r.qty,r.good_qty,r.damaged_qty,b.batch_ref FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id WHERE r.platform=? AND r.original_ref=? AND r.product_id=? AND r.qty=? AND r.reversed=0 ORDER BY r.id DESC LIMIT 1");$q->execute([$row['platform'],$row['order'],$row['product_id'],$row['qty']]);if($old=$q->fetch()){$row['possible_duplicate']=$old['batch_ref'];$warnings[]='Row '.$row['row'].': similar prior return '.$old['batch_ref'].($row['condition']==='Damaged / Leak'?'; uploader must verify a separate physical return and explain it in Remarks.':'; confirm a separate physical return with remarks and Admin review.');}
 }catch(Throwable $e){$row['errors'][]=$e->getMessage();$errors[]='Row '.$row['row'].': '.$e->getMessage();}$checked[]=$row;}
 if(!$checked)$errors[]='No return rows found.';return ['rows'=>$checked,'errors'=>$errors,'warnings'=>$warnings,'digest'=>hash('sha256',json_encode([$b['revision'],$checked]))];}
function return_stage($rows,$filename=null,$stored=null,$hash=null){return process_transaction(function()use($rows,$filename,$stored,$hash){inflow_require_controls();if($hash){$q=db()->prepare("SELECT batch_ref,id,status FROM return_batches WHERE file_hash=? AND status IN ('Review','Posted') ORDER BY id LIMIT 1");$q->execute([$hash]);if($old=$q->fetch())throw new Exception('This return file is already uploaded: '.$old['batch_ref'].' (#'.$old['id'].', '.$old['status'].'). Open the existing return.');}db()->prepare('INSERT INTO return_batches(batch_ref,filename,stored_path,file_hash,rows_json,created_by) VALUES(?,?,?,?,?,?)')->execute([next_ref('RET').'-'.bin2hex(random_bytes(3)),$filename,$stored,$hash,json_encode($rows),current_user()['id']]);$id=(int)db()->lastInsertId();audit('Review order return','Return',(string)$id,'No inventory added.');inflow_sync_return_history($id);return $id;});}
function return_manual_stage($input,$file=null){if(($input['reference_kind']??'')!=='Return Order')throw new Exception('Return borrowed items from their Borrowed Items record.');$p=active_product((int)($input['product_id']??0));[$factor,$qty]=receipt_quantity($input['source_qty']??0,$input['source_uom']??'pc');$row=['row'=>1,'date'=>$input['txn_date']??'','order'=>$input['order_id']??'','platform'=>$input['destination_platform']??'','product_id'=>$p['id'],'item'=>$p['name'],'qty'=>$qty,'condition'=>$input['item_condition']??'','remarks'=>trim($input['remarks']??'')];$stored=!empty($file['tmp_name'])?store_upload($file,'return_attachments','RETURN'):null;return return_stage([$row],$file['name']??'Manual Order Return',$stored);}
function return_excel_stage($file){validate_upload_file($file,['xlsx']);$rows=XlsxReader::rows($file['tmp_name']);$hr=find_header_row($rows,[['Date','Product Description / SKU','Quantity','Platform','Order ID','Item Condition']]);if($hr===null)throw new Exception('Use the downloadable Order Return template. Do not rename its columns.');$col=array_flip(array_map('norm',$rows[$hr]));$items=[];foreach(array_slice($rows,$hr+1) as $i=>$r){if(!array_filter($r,fn($v)=>trim((string)$v)!==''))continue;$item=trim($r[$col['product description / sku']]??'');$rawDate=$r[$col['date']]??'';$date=is_numeric($rawDate)?excel_date($rawDate):trim($rawDate);$items[]=['row'=>$hr+$i+2,'date'=>$date,'order'=>trim($r[$col['order id']]??''),'platform'=>trim($r[$col['platform']]??''),'product_id'=>return_match($item),'item'=>$item,'qty'=>trim($r[$col['quantity']]??''),'condition'=>trim($r[$col['item condition']]??''),'remarks'=>trim($r[$col['remarks']??9999]??'')];}$hash=hash_file('sha256',$file['tmp_name']);$stored=store_upload($file,'order_returns','RET-XLSX');return return_stage($items,basename($file['name']),$stored,$hash);}
function return_save_row($id,$rowNo,$revision,$input){return process_transaction(function()use($id,$rowNo,$revision,$input){$b=return_batch($id,true);if($b['status']!=='Review'||(int)$b['revision']!==(int)$revision)throw new Exception('Return review changed. Refresh it first.');$rows=json_decode($b['rows_json'],true);$found=false;foreach($rows as &$r)if((int)$r['row']===$rowNo){$r=array_replace($r,['date'=>$input['date']??'','order'=>$input['order']??'','platform'=>$input['platform']??'','product_id'=>(int)($input['product_id']??0),'qty'=>$input['qty']??'','condition'=>$input['condition']??'','remarks'=>trim($input['remarks']??'')]);unset($r['parse_error']);$found=true;break;}unset($r);if(!$found)throw new Exception('Return row not found.');db()->prepare('UPDATE return_batches SET rows_json=?,revision=revision+1 WHERE id=?')->execute([json_encode($rows),$id]);inflow_sync_return_history($id);audit('Correct order return','Return',$b['batch_ref'],'Row '.$rowNo.' corrected; inventory unchanged.');});}
function return_confirm($id,$digest,$ack){if(!$ack)throw new Exception('Confirm the reviewed return first.');return process_transaction(function()use($id,$digest){$b=return_batch($id,true);if($b['status']!=='Review')throw new Exception('Return is already posted or cancelled.');$rows=json_decode($b['rows_json'],true);$ids=array_unique(array_column($rows,'product_id'));sort($ids,SORT_NUMERIC);foreach($ids as $pid)db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);$a=return_analysis($b);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));if(!hash_equals($a['digest'],(string)$digest))throw new Exception('Order balances or review changed. Refresh final confirmation.');if(!return_uploader_allowed($b,$a))throw new Exception(return_requires_admin_review($a)?'Possible Duplicate good / repackaging returns require Admin review.':'The uploader must validate and submit this Damage / Leak return.');if($a['warnings']){foreach($a['rows'] as $r)if(isset($r['possible_duplicate']))process_reason($r['remarks']);}
 foreach($a['rows'] as $r){$pid=(int)$r['product_id'];check_platform_alignment($pid);$good=$r['condition']==='Good Item'?$r['qty']:0;$damage=$r['condition']==='Damaged / Leak'?$r['qty']:0;$repack=$r['condition']==='For Repackaging'?$r['qty']:0;$restricted=$damage+$repack;$inflow=null;$ns=null;if($good){db()->prepare('INSERT INTO inflows(txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$r['date'],$b['batch_ref'],$r['order'],$r['platform'],$pid,$good,'pc',$good,'Order Return',$r['remarks'],current_user()['id']]);$inflow=(int)db()->lastInsertId();change_platform_stock($r['platform'],$pid,$good,$b['batch_ref'],$r['date']);}if($restricted){db()->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,0,?,?)')->execute([$r['date'],$r['platform'],$b['batch_ref'],$pid,$restricted,$repack?'For Repackaging':'Damaged / Leak','Return Order',$repack?'Pending':'For Review','Order Return',$r['order'].'; '.$r['remarks'],current_user()['id']]);$ns=(int)db()->lastInsertId();if($repack)packaging_initialize($ns);}db()->prepare('INSERT INTO posted_returns(batch_id,platform,original_ref,product_id,qty,good_qty,damaged_qty,txn_date,user_id,dedupe_key,inflow_id,non_sellable_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$r['platform'],$r['order'],$pid,$r['qty'],$good,$damage,$r['date'],current_user()['id'],hash('sha256','return|'.$id.'|'.$r['row']),$inflow,$ns]);if($repack)db()->prepare('UPDATE posted_returns SET repackaging_qty=? WHERE id=?')->execute([$repack,(int)db()->lastInsertId()]);check_platform_alignment($pid);}
 db()->prepare("UPDATE return_batches SET status='Posted',posted_by=?,posted_at=NOW(),rows_json=? WHERE id=?")->execute([current_user()['id'],json_encode($a['rows']),$id]);inflow_sync_return_history($id);audit('Confirm order return','Return',$b['batch_ref'],count($a['rows']).' rows; restored to original platform / Non-Sellable.'.(return_damage_only($b)?' Uploader validation; no separate Admin approval required.':''));return count($a['rows']);});}
function return_cancel($id){return process_transaction(function()use($id){$b=return_batch($id,true);if($b['status']!=='Review')throw new Exception('Only unposted return uploads can be cancelled.');db()->prepare("UPDATE return_batches SET status='Cancelled' WHERE id=?")->execute([$id]);inflow_sync_return_history($id);audit('Cancel order return','Return',$b['batch_ref'],'No inventory added.');});}
